func lookupModelCost(name string) ([costFieldCount]float64, bool) {
	low := 0
	high := len(modelCostTable) - 1
	for low <= high {
		mid := (low + high) / 2
		switch {
		case modelCostTable[mid].name < name:
			low = mid + 1
		case modelCostTable[mid].name > name:
			high = mid - 1
		default:
			return modelCostTable[mid].cost, true
		}
	}
	return [costFieldCount]float64{}, false
}
